CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, type TEXT NOT NULL CHECK(type IN ('passport','national_id','residency')), number TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, nationality TEXT NOT NULL, birth_date TEXT, issued_at TEXT NOT NULL, expires_at TEXT NOT NULL, issuer TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'valid' CHECK(status IN ('valid','suspended','cancelled')), notes TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_documents_number ON documents(number);
CREATE TABLE IF NOT EXISTS circulars (id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, document_id TEXT NOT NULL REFERENCES documents(id), kind TEXT NOT NULL, reason TEXT NOT NULL, confidentiality TEXT NOT NULL DEFAULT 'restricted' CHECK(confidentiality IN ('restricted','public')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','cancelled')), expires_at TEXT, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_circulars_document ON circulars(document_id,status);
CREATE TABLE IF NOT EXISTS document_checks (id TEXT PRIMARY KEY, document_number TEXT NOT NULL, document_id TEXT, checked_by TEXT NOT NULL REFERENCES users(id), result TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS civil_intake (id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, full_name TEXT NOT NULL, parent_name TEXT, birth_date TEXT, details TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'recorded', created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), subject TEXT NOT NULL, body TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
